-- Ask my tutor for ALL lessons in the existing Year 9 and Year 10 courses.
-- Run this ENTIRE file in a NEW Supabase SQL Editor query.
-- Safe to rerun; preserves all flags/history and does not change learning records.
-- Self-contained: works with or without the original flags trial migration.
begin;
create table if not exists public.question_flags (
 id uuid primary key,
 student_id uuid references public.profiles(id) on delete set null,
 course_id uuid references public.courses(id) on delete set null,
 lesson_id uuid references public.lessons(id) on delete set null,
 question_id uuid references public.questions(id) on delete set null,
 status text not null default 'outstanding' check(status in ('outstanding','reviewed','withdrawn')),
 context jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(),
 closed_at timestamptz,
 reviewed_by uuid references public.profiles(id) on delete set null,
 reviewer_name text,
 check((status='outstanding' and closed_at is null) or (status<>'outstanding' and closed_at is not null))
);
create unique index if not exists question_flags_one_active_idx
 on public.question_flags(student_id,question_id) where status='outstanding';
create index if not exists question_flags_student_date_idx on public.question_flags(student_id,created_at desc);
alter table public.question_flags enable row level security;
do $$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='question_flags' and policyname='question_flags_read') then
  create policy question_flags_read on public.question_flags for select to authenticated
   using(student_id=auth.uid() or public.is_tutor());
 end if;
end $$;
revoke all on public.question_flags from public,anon,authenticated;
grant select on public.question_flags to authenticated;

-- Two scope records, linked to existing courses; no student/content data is copied.
create table if not exists public.question_flag_courses (
 course_id uuid primary key references public.courses(id) on delete cascade
);
alter table public.question_flag_courses enable row level security;
do $$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='question_flag_courses' and policyname='question_flag_courses_read') then
  create policy question_flag_courses_read on public.question_flag_courses for select to authenticated
   using(public.is_tutor() or exists(select 1 from public.enrolments e where e.course_id=question_flag_courses.course_id and e.student_id=auth.uid()));
 end if;
end $$;
revoke all on public.question_flag_courses from public,anon,authenticated;
grant select on public.question_flag_courses to authenticated;

do $$
declare year9 uuid; year10 uuid[];
begin
 select m.course_id into year9 from public.lessons l join public.modules m on m.id=l.module_id
 where l.id='1313fc50-2b9a-405d-a64a-7f385a1db1b8'::uuid;
 if year9 is null then raise exception 'The existing Year 9 course could not be identified.'; end if;
 select array_agg(scope.course_id) into year10 from (
  select m.course_id from public.questions q join public.lessons l on l.id=q.lesson_id join public.modules m on m.id=l.module_id
  where q.id=any(array[
